package android.content;import java.util.*;public interface SharedPreferences {Map<String,?> getAll();String getString(String k,String d);default boolean getBoolean(String k,boolean d){return Boolean.parseBoolean(getString(k,Boolean.toString(d)));}Editor edit();interface Editor {default Editor remove(String k){return putString(k,"");}Editor putString(String k,String v);default Editor putBoolean(String k,boolean v){return putString(k,Boolean.toString(v));}void apply();boolean commit();}}
